const groups = $input.first().json.result.groups;
const hits = groups.flatMap(g => g.hits).sort((a, b) => b.score - a.score);

const contexto = hits.map((h, i) =>
  `[Fuente ${i + 1}] ${h.payload.metadata.documento}, página ${h.payload.metadata.pagina}\n${h.payload.content}`
).join('\n\n---\n\n');

const fuentes = hits.map((h, i) => ({
  n: i + 1,
  documento: h.payload.metadata.documento,
  pagina: h.payload.metadata.pagina,
  score: Math.round(h.score * 100) / 100
}));

return [{ json: { pregunta: $('Webhook - Pregunta').first().json.body.pregunta, contexto, fuentes } }];

const original = $input.first().json.text;
let r = original.replace(/\[Fuente\s*(\d+)\]/gi, '[$1]');

const todas = $('Contexto').first().json.fuentes;
const porN = new Map(todas.map(f => [f.n, f]));
const numPorClave = new Map();
const fuentes = [];

r = r.replace(/\[(\d+)\]/g, (_, n) => {
  const f = porN.get(Number(n));
  if (!f) return '';
  const clave = f.documento + '|' + f.pagina;
  if (!numPorClave.has(clave)) {
    numPorClave.set(clave, numPorClave.size + 1);
    fuentes.push({ n: numPorClave.get(clave), documento: f.documento, pagina: f.pagina, score: f.score });
  }
  return `[${numPorClave.get(clave)}]`;
});

r = r.replace(/(\[\d+\])(\1)+/g, '$1');

return [{
  json: {
    respuesta: r,
    busqueda: $('Reescribir búsqueda').first().json.text,
    fuentes
  }
}];
